mapper.select:
SELECT 
    FLOOR((CAST(${columnName} AS DOUBLE PRECISION) - #{minValue}) / #{intervalWidth}) as interval_index,
    COUNT(*) as count,
    MIN(CAST(${columnName} AS DOUBLE PRECISION)) as min_value,
    MAX(CAST(${columnName} AS DOUBLE PRECISION)) as max_value
FROM ${tableName}
WHERE CAST(${columnName} AS DOUBLE PRECISION) >= #{minValue}
  AND CAST(${columnName} AS DOUBLE PRECISION) <= #{maxValue}
  AND area_id = #{areaId}
GROUP BY interval_index
ORDER BY interval_index

SELECT 
    CAST(${xColumnName} AS DOUBLE PRECISION) as x,
    CAST(${yColumnName} AS DOUBLE PRECISION) as y
FROM ${tableName}
WHERE RANDOM() < #{sampleRate}
  AND area_id = #{areaId}
